"""Source-coded, non-exhaustive literature sample. Run before plot_landscape.py."""
import json
from collections import Counter
from pathlib import Path
ROOT = Path(__file__).resolve().parent
# T: structure construction/editing; E: energy/electronic properties; O: relaxation;
# F: vibrations/thermochemistry; R: reaction paths/TS; D: dynamics/sampling.
rows = []
def add(name, date, group, target, boundary, tasks, url, locator, evidence, family=None, aliases=(), limits=''):
    rows.append(dict(id=name.lower().replace(' ', '_').replace('/', '_'), name=name,
      first_public_date=date, physical_target=group, demonstrated_target=target,
      boundary_conditions=boundary, demonstrated_tasks=list(tasks),
      task_evidence={t:dict(source_index=0) for t in tasks},
      sources=[dict(url=url, locator=locator, evidence_paraphrase=evidence)],
      family=family or name, aliases=list(aliases), limitations=limits,
      include_main=True, reviewed_on='2026-10-26'))
M='extended_materials_surfaces'; Q='finite_molecules_complexes'; S='soft_biomolecular'
