ROOT.mkdir(parents=True, exist_ok=True)
(ROOT/'systems').mkdir(exist_ok=True)
for r in rows:
    (ROOT/'systems'/f"{r['id']}.json").write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n')
(ROOT/'systems.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
