tasks = Counter(t for r in rows for t in r['demonstrated_tasks'])
summary={'sample_n':len(rows),'physical_target_counts':dict(counts),'positive_task_counts':dict(tasks),'counts_are_non_exhaustive':True,'boundary_conditions_are_not_physical_target':True}
